#!/usr/bin/env python3
"""Isolated GitHub App worker. Never imports or executes code from a PR.

Run periodically from the protected publisher workflow or a trusted host. The policy and App key belong to that
host, never to a validation job. See README.md before deploying.
"""
import argparse
import base64
import hashlib
import io
import json
import os
import re
import subprocess
import time
import urllib.error
import urllib.parse
import urllib.request
import zipfile
from dataclasses import dataclass
from pathlib import Path

API = "https://api.github.com"
CONTEXT = "CI result"
PROVENANCE_JOB = "CI provenance"


class NotReady(Exception):
    """Missing evidence must never become a successful check."""


@dataclass(frozen=True)
class Result:
    status: str
    explanation: str
    runs: tuple = ()


def git_blob(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()


def read_provenance(archive):
    """Read one small JSON member in memory; never extract attacker paths."""
    if len(archive) > 65536:
        raise NotReady("Oversized provenance archive")
    try:
        with zipfile.ZipFile(io.BytesIO(archive)) as z:
            entries = z.infolist()
            if len(entries) != 1 or entries[0].filename != "provenance.json":
                raise NotReady("Unexpected provenance archive members")
            if entries[0].file_size > 16384 or entries[0].compress_type not in (0, 8):
                raise NotReady("Oversized or unsupported provenance member")
            value = json.loads(z.read(entries[0]))
            if not isinstance(value, dict):
                raise NotReady("Provenance is not an object")
            return value
    except (zipfile.BadZipFile, ValueError, RuntimeError, KeyError) as exc:
        raise NotReady("Invalid provenance archive") from exc


def matches(path, patterns):
    """Conservative subset of GitHub globs. Unsupported syntax fails closed.

    Policies generated by prepare.py currently use *, ** and ?. Negation,
    extglobs and character classes require a reviewed selector implementation.
    """
    for pattern in patterns:
        if any(c in pattern for c in "![]{}()+\\"):
            raise NotReady("Unsupported path selector: " + pattern)
        parts, i = [], 0
        while i < len(pattern):
            if pattern[i:i+3] == "**/":
                parts.append("(?:.*/)?"); i += 3
            elif pattern[i:i+2] == "**":
                parts.append(".*"); i += 2
            elif pattern[i] == "*":
                parts.append("[^/]*"); i += 1
            elif pattern[i] == "?":
                parts.append("[^/]"); i += 1
            else:
                parts.append(re.escape(pattern[i])); i += 1
        if re.fullmatch("".join(parts), path):
            return True
    return False


def applicable(workflow, changes, target=None):
    patterns = workflow.get("configured_branches", [])
    if patterns and target is not None:
        selected = False
        for pattern in patterns:
            if pattern == "dev[0-9]*":
                selected |= bool(re.fullmatch(r"dev[0-9].*", target))
            elif re.fullmatch(r"[A-Za-z0-9_./-]+", pattern):
                selected |= pattern == target
            else:
                raise NotReady("Unsupported branch selector: " + pattern)
        if not selected:
            return False
    if changes is None or not changes:
        raise NotReady("Missing or empty changed-file inventory")
    # Renames include both paths: changing a tested file into an ignored path
    # must not become an automatic no-tests result.
    if workflow.get("paths"):
        return any(matches(p, workflow["paths"]) for p in changes)
    if workflow.get("paths_ignore"):
        return not all(matches(p, workflow["paths_ignore"]) for p in changes)
    return True


def fingerprint(pr):
    return (pr["number"], pr["head"]["sha"], pr["base"]["sha"],
            pr["base"]["ref"], pr.get("merge_commit_sha"), pr["state"])


def allowed_skips(workflow, changes):
    """Only independently justified exclusions from a pinned workflow graph."""
    allowed = set(workflow.get("unselected_jobs", []))
    selection = workflow.get("selection")
    if selection:
        if selection.get("type") != "templates" or not selection.get("template_paths"):
            raise NotReady("Unsupported or incomplete selection policy")
        selected = (any(p in ("templates.json", "test_template.sh") for p in changes)
                    or any(p.split("/")[0] in selection["template_paths"] for p in changes))
        if not selected:
            allowed.update(("ios-pr", "android-pr"))
    return allowed


def assess(pr, policy, changes, evidence):
    """Pure decision function; evidence comes only from authenticated API reads."""
    accepted = []
    try:
        if pr["state"] != "open" or not pr.get("merge_commit_sha"):
            raise NotReady("PR is closed or GitHub has not computed a merge commit")
        if pr["base"]["repo"]["id"] != policy["repository_id"]:
            raise NotReady("Repository identity mismatch")
        branch = policy["branches"].get(pr["base"]["ref"])
        if not branch or not branch.get("workflows"):
            raise NotReady("Target branch has not been onboarded")
        for workflow in branch["workflows"]:
            if not applicable(workflow, changes, pr["base"]["ref"]):
                continue
            item = evidence.get(workflow["path"])
            if not item:
                raise NotReady("Missing workflow: " + workflow["path"])
            run, jobs, provenance = item["run"], item["jobs"], item.get("provenance")
            if (run["repository"]["id"] != policy["repository_id"]
                    or run["head_sha"] != pr["head"]["sha"]
                    or run["head_repository"]["id"] != pr["head"]["repo"]["id"]
                    or run["path"] != workflow["path"]
                    or run["event"] != workflow["event"]
                    or run["workflow_id"] != workflow["id"]):
                raise NotReady("Run identity mismatch: " + workflow["path"])
            accepted.append((run["id"], run["run_attempt"]))
            if run["status"] != "completed":
                raise NotReady("Validation is still running")
            if run["conclusion"] != "success":
                return Result("failure", "Workflow concluded " + str(run["conclusion"]), tuple(accepted))
            if not provenance:
                raise NotReady("Missing provenance for latest attempt")
            expected = {
                "repository": policy["repository"], "repository_id": str(policy["repository_id"]),
                "run_id": str(run["id"]), "run_attempt": str(run["run_attempt"]),
                "event": workflow["event"], "workflow_path": workflow["path"],
                "pr": str(pr["number"]), "head_sha": pr["head"]["sha"],
                "head_repository_id": str(pr["head"]["repo"]["id"]),
                "base_sha": pr["base"]["sha"], "base_ref": pr["base"]["ref"],
            }
            if any(provenance.get(k) != v for k, v in expected.items()):
                raise NotReady("Stale or mismatched provenance")
            if not item.get("trusted_source"):
                raise NotReady("Workflow or selection source has not been approved")
            if not item.get("valid_commit_binding"):
                raise NotReady("Executed commit is not bound to this head and base")
            if not jobs or any(j.get("run_attempt") != run["run_attempt"] for j in jobs):
                raise NotReady("Missing jobs or jobs from another attempt")
            reporters = [j for j in jobs if j["name"] == PROVENANCE_JOB]
            real_jobs = [j for j in jobs if j["name"] != PROVENANCE_JOB]
            if len(reporters) != 1 or reporters[0].get("conclusion") != "success" or not real_jobs:
                raise NotReady("Provenance job or real validation jobs missing")
            allowed = allowed_skips(workflow, changes)
            selected_jobs = []
            for job in real_jobs:
                if job["status"] != "completed":
                    raise NotReady("A selected job is incomplete")
                if job["conclusion"] == "skipped" and job["name"] in allowed:
                    continue
                selected_jobs.append(job)
                if job["conclusion"] != "success":
                    return Result("failure", "Selected job did not succeed: " + job["name"], tuple(accepted))
            if not selected_jobs:
                raise NotReady("No selected validation jobs ran")
        if not accepted:
            raise NotReady("No applicable validation ran")
        return Result("success", "All applicable workflows and selected jobs succeeded", tuple(accepted))
    except (NotReady, KeyError, TypeError) as exc:
        return Result("pending", str(exc), tuple(accepted))


class GitHub:
    def __init__(self, token):
        self.token = token
        self.trees = {}

    def request(self, path, data=None, method=None):
        if not path.startswith("/") or path.startswith("//"):
            raise ValueError("API path must be relative to api.github.com")
        request = urllib.request.Request(API + path,
            data=None if data is None else json.dumps(data).encode(), method=method,
            headers={"Authorization": "Bearer " + self.token,
                     "Accept": "application/vnd.github+json", "Content-Type": "application/json",
                     "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "msdk-ci-result-publisher"})
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.load(response)

    def pages(self, path, key=None):
        result = []
        for page in range(1, 101):
            data = self.request(path + ("&" if "?" in path else "?") + f"per_page=100&page={page}")
            values = data[key] if key else data
            result.extend(values)
            if len(values) < 100:
                return result
        raise NotReady("API pagination limit reached")

    def blob(self, repo, sha, path):
        data = self.request(f"/repos/{repo}/contents/{urllib.parse.quote(path)}?ref={sha}")
        if data.get("type") != "file" or data.get("encoding") != "base64":
            raise NotReady("Source is not a regular file")
        return base64.b64decode(data["content"])

    def trusted_tree(self, repo, revision, approved):
        key = (repo, revision)
        if key not in self.trees:
            self.trees[key] = self.request(f"/repos/{repo}/git/trees/{revision}?recursive=1")
        tree = self.trees[key]
        if tree.get("truncated"):
            raise NotReady("Source tree inventory truncated")
        actual = {e["path"]: e["sha"] for e in tree["tree"]
                  if e["type"] == "blob" and (e["path"].startswith(".github/workflows/")
                      or e["path"].startswith(".github/DangerFiles/"))}
        return (bool(approved) and actual.keys() == approved.keys()
                and all(sha in approved[path] for path, sha in actual.items()))

    def artifact(self, repo, artifact_id):
        # GitHub redirects archive downloads to signed object-storage URLs.
        # Strip Authorization on redirects; never send the App token there.
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs):
                return None
        req = urllib.request.Request(f"{API}/repos/{repo}/actions/artifacts/{artifact_id}/zip",
            headers={"Authorization": "Bearer " + self.token, "User-Agent": "msdk-ci-result-publisher"})
        try:
            urllib.request.build_opener(NoRedirect).open(req, timeout=30)
        except urllib.error.HTTPError as exc:
            if exc.code != 302:
                raise
            url = exc.headers["Location"]
            if urllib.parse.urlparse(url).scheme != "https":
                raise NotReady("Artifact redirect is not HTTPS")
            with urllib.request.urlopen(url, timeout=30) as response:
                return response.read(65537)
        raise NotReady("Expected a signed artifact redirect")


def installation_client(app_id, key_file, repo_id, repository):
    def encode(value):
        return base64.urlsafe_b64encode(value).rstrip(b"=")
    now = int(time.time())
    message = encode(b'{"alg":"RS256","typ":"JWT"}') + b"." + encode(json.dumps(
        {"iat": now-60, "exp": now+540, "iss": str(app_id)}, separators=(",", ":")).encode())
    signature = subprocess.run(["openssl", "dgst", "-sha256", "-sign", key_file],
                               input=message, stdout=subprocess.PIPE, check=True).stdout
    app = GitHub((message + b"." + encode(signature)).decode())
    installation = app.request(f"/repos/{repository}/installation")
    if installation["app_id"] != app_id:
        raise NotReady("Installation belongs to a different App")
    token = app.request(f'/app/installations/{installation["id"]}/access_tokens', {
        "repository_ids": [repo_id], "permissions": {
            "actions": "read", "contents": "read", "pull_requests": "read", "checks": "write"}})
    return GitHub(token["token"])


def collect(api, repo_policy, pr):
    repo = repo_policy["repository"]
    files = api.pages(f'/repos/{repo}/pulls/{pr["number"]}/files')
    if len(files) != pr["changed_files"] or len(files) >= 3000:
        raise NotReady("Changed-file inventory incomplete")
    changes = sorted({p for f in files for p in (f["filename"], f.get("previous_filename", f["filename"]))})
    branch = repo_policy["branches"].get(pr["base"]["ref"], {})
    evidence = {}
    for workflow in branch.get("workflows", []):
        if not applicable(workflow, changes, pr["base"]["ref"]):
            continue
        if not workflow.get("id"):
            raise NotReady("Workflow ID not enrolled: " + workflow["path"])
        runs = api.pages(f'/repos/{repo}/actions/workflows/{workflow["id"]}/runs?head_sha={pr["head"]["sha"]}&event={workflow["event"]}', "workflow_runs")
        runs = [r for r in runs if r["head_repository"] and r["head_repository"]["id"] == pr["head"]["repo"]["id"]]
        if not runs:
            continue
        # Never fall back to an earlier successful run or attempt.
        run = max(runs, key=lambda r: r["id"])
        run = api.request(f'/repos/{repo}/actions/runs/{run["id"]}')
        jobs = api.pages(f'/repos/{repo}/actions/runs/{run["id"]}/attempts/{run["run_attempt"]}/jobs', "jobs")
        item = {"run": run, "jobs": jobs}
        evidence[workflow["path"]] = item
        if run["status"] != "completed" or run["conclusion"] != "success":
            continue
        artifacts = api.pages(f'/repos/{repo}/actions/runs/{run["id"]}/artifacts', "artifacts")
        expected_name = f'ci-provenance-{run["id"]}-{run["run_attempt"]}'
        artifacts = [a for a in artifacts if a["name"] == expected_name and not a["expired"]]
        if len(artifacts) != 1:
            continue
        provenance = read_provenance(api.artifact(repo, artifacts[0]["id"]))
        item["provenance"] = provenance
        source = provenance.get("workflow_sha", "")
        if not re.fullmatch(r"[0-9a-f]{40}", source):
            continue
        # Compare the entire reviewed workflow graph and selectors, not names
        # supplied by a PR. Every approved path must match both executed source
        # and PR head. New/modified workflow files require a policy update.
        item["trusted_source"] = all(api.trusted_tree(repo, revision, branch.get("trusted_files", {}))
                                     for revision in {source, pr["head"]["sha"]})
        for reference in run.get("referenced_workflows", []):
            prefix = repo + "/.github/workflows/"
            ref_sha = reference.get("sha", "")
            if (not reference.get("path", "").startswith(prefix)
                    or not re.fullmatch(r"[0-9a-f]{40}", ref_sha)
                    or not api.trusted_tree(repo, ref_sha, branch.get("trusted_files", {}))):
                item["trusted_source"] = False
        if workflow["event"] == "pull_request":
            commit = api.request(f'/repos/{repo}/git/commits/{source}')
            item["valid_commit_binding"] = (provenance.get("sha") == source
                and [p["sha"] for p in commit["parents"]] == [pr["base"]["sha"], pr["head"]["sha"]])
        elif workflow["event"] == "pull_request_target":
            item["valid_commit_binding"] = provenance.get("sha") == pr["base"]["sha"]
    return changes, evidence


def publish(api, app_id, repo_policy, pr, result, policy_digest):
    repo, merge = repo_policy["repository"], pr["merge_commit_sha"]
    checks = api.pages(f'/repos/{repo}/commits/{merge}/check-runs?filter=all', "check_runs")
    own = [c for c in checks if c["name"] == CONTEXT and c["app"]["id"] == app_id]
    if len(own) > 1:
        raise NotReady("Multiple App-owned CI result checks; reconcile manually")
    summary = json.dumps({"pr": pr["number"], "head": pr["head"]["sha"], "base": pr["base"]["sha"],
                          "merge": merge, "policy_sha256": policy_digest, "runs": result.runs}, indent=2)
    body = {"name": CONTEXT, "status": "in_progress" if result.status == "pending" else "completed",
            "external_id": f'msdk:{repo_policy["repository_id"]}:{pr["number"]}:{merge}',
            "details_url": pr["html_url"], "output": {"title": result.explanation[:255], "summary": "```json\n" + summary + "\n```"}}
    if result.status != "pending":
        body["conclusion"] = result.status
    if own:
        api.request(f'/repos/{repo}/check-runs/{own[0]["id"]}', body, method="PATCH")
    else:
        api.request(f'/repos/{repo}/check-runs', dict(body, head_sha=merge))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--app-id", type=int)
    parser.add_argument("--key-file")
    parser.add_argument("--write", action="store_true", help="Publish checks using the dedicated App only")
    args = parser.parse_args()
    raw = args.policy.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    policies = json.loads(raw)["repositories"]
    if args.write and (not args.app_id or not args.key_file):
        parser.error("--write requires a dedicated App ID and private key")
    if args.write and any(not w.get("id") for p in policies for b in p["branches"].values() for w in b["workflows"]):
        parser.error("Policy contains unenrolled workflow IDs; finish onboarding before publishing")
    for policy in policies:
        api = (installation_client(args.app_id, args.key_file, policy["repository_id"], policy["repository"])
               if args.app_id else GitHub(os.environ["GH_TOKEN"]))
        repo = policy["repository"]
        for listing in api.pages(f"/repos/{repo}/pulls?state=open"):
            pr = api.request(f'/repos/{repo}/pulls/{listing["number"]}')
            if pr["base"]["ref"] not in policy["branches"]:
                continue
            try:
                changes, evidence = collect(api, policy, pr)
                result = assess(pr, policy, changes, evidence)
            except (NotReady, urllib.error.HTTPError, TimeoutError, KeyError, ValueError) as exc:
                result = Result("pending", "Evidence collection failed: " + type(exc).__name__)
            latest = api.request(f'/repos/{repo}/pulls/{pr["number"]}')
            if fingerprint(latest) != fingerprint(pr):
                print(json.dumps({"repo": repo, "pr": pr["number"], "status": "superseded"}))
                continue
            if args.write and pr.get("merge_commit_sha") and pr["state"] == "open":
                publish(api, args.app_id, policy, pr, result, digest)
            print(json.dumps({"repo": repo, "pr": pr["number"], "head": pr["head"]["sha"],
                              "status": result.status, "reason": result.explanation, "runs": result.runs,
                              "policy_sha256": digest}))


if __name__ == "__main__":
    main()
